changeSet.sql:
ALTER TABLE "${schema}".employee_profile_change_request
ADD CONSTRAINT chk_profile_change_payload_encryption_version
CHECK (
    (requested_payload_encrypted IS NULL AND payload_encryption_version IS NULL)
    OR (requested_payload_encrypted IS NOT NULL AND payload_encryption_version = 1)
);

CREATE OR REPLACE FUNCTION "${schema}".prevent_audit_log_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $body$
BEGIN
    RAISE EXCEPTION 'audit_log is append-only';
END;
$body$;

CREATE TRIGGER trg_audit_log_append_only
BEFORE UPDATE OR DELETE ON "${schema}".audit_log
FOR EACH ROW EXECUTE FUNCTION "${schema}".prevent_audit_log_mutation();
